\begin{definition}[Second subderivative, {\cite[Defintion 13.3]{RoWe98}}]
Let $\varphi: \R^n\to \bar \R$, $\varphi(z)$ be finite and $z^*\in  \mathbb{R}^n$. The second subderivative of $\varphi$ at $z$ for $z^*$  is a function defined by
 \begin{eqnarray*}
 {\rm d}^2\varphi(z;z^*)(w):= \liminf\limits_{{t\downarrow 0} \atop {w'\to w}} \frac{\varphi(z+tw')-\varphi(z)-t\langle z^*, w'\rangle}{\frac{1}{2}t^2}
 % \bigtriangleup_{t}^2 \varphi (\bar x;z^*)(w'),
 \qquad \forall w \in  \mathbb{R}^n.
 %\\ &&  \mbox{ where }  \bigtriangleup_{t}^2 \varphi (\bar x;z^*)(w'):=\frac{\varphi(\bar{x}+tw')-\varphi(\bar{x})-t\langle \bar{v}, w'\rangle}{\frac{1}{2}t^2}  .
\end{eqnarray*}
 \end{definition}

By definition, the second subderivative of the indicator function $\delta_S$ of a set
$S$ at $z\in S$ for $z^*$ is
\begin{eqnarray}
{\rm d}^2\delta_{S}(z;z^*)(w)
 =\liminf\limits_{{t\downarrow 0} \atop w'\to w}\frac{\delta_{S}(z+tw')-\delta_{S}(z)-t\langle z^*, w' \rangle }{\frac{1}{2}t^2}
=\liminf\limits_{{t\downarrow 0, w'\to w} \atop { z+tw' \in S }}\frac{-2\langle z^*, w' \rangle }{t}. \label{indicatorf}
 \end{eqnarray}

