 Let $\bar x$ be a feasible point of problem (GP).
 Suppose that for every $u\in \mathcal{C}(\bar x ) \backslash \{0\}$ there is $\alpha\geq 0$ and $\lambda\in \R^m$ such that
 \begin{equation}\label{Alpha}
 \nabla_x L^\alpha (\bar x,\lambda)=0\end{equation}
  and
  \begin{equation}\label{alpha-sufficient}
   \nabla^2_{xx}L^\alpha(\bar{x},\lambda)(u,u)+{\rm d}^2\delta_{C}(g(\bar{x});\lambda)(\nabla g(\bar{x})u)>0.
  \end{equation}
  Then $\bar{x}$ is an essential local minimizer of second order.
 \end{theorem}

