  Then $\bar{x}$ is an essential local minimizer of second order.
 \end{theorem}

Let $\bar x$ be a feasible point of problem (GP).
Suppose that for every $u\in \mathcal{C}(\bar x ) \backslash \{0\}$ there is $\alpha\geq 0$ and $\lambda\in \R^m$ such that
\begin{equation}\label{Alpha}
\nabla_x L^\alpha (\bar x,\lambda)=0\end{equation}
 and
 \begin{equation}\label{alpha-sufficient}
  \nabla^2_{xx}L^\alpha(\bar{x},\lambda)(u,u)+{\rm d}^2\delta_{C}(g(\bar{x});\lambda)(\nabla g(\bar{x})u)>0.
 \end{equation}

\begin{proof}
 By contradiction, if $\bar{x}$ is not an essential local minimizer of second order, then there exists a sequence $x_k$ converging to $\xb$ such that
\begin{eqnarray}
&&  f(x_k)-f(\bar{x})\leq o(\|x_k-\bar{x}\|^2), \label{cqg}\\
&&  {\rm dist}(g(x_k),C)\leq o(\|x_k-\bar{x}\|^2).\label{distance}
 \end{eqnarray}

Let $t_k:=\|x_k-\bar{x}\|$ and $u_k:=(x_k-\bar{x})/t_k$.
We assume without loss of generality that $u_k$ is converging to $u$.
From equation \eqref{cqg} it readily follows that $\nabla f(\xb)u\leq 0$ and
 \begin{equation}\label{f-inequality}
\liminf\limits_{k}-\frac{f(x_k)-f(\bar{x})}{\frac{1}{2}t_k^2}\geq 0.
\end{equation}
